// 重复请求、中断和开始后失权都不生成第二份人口或凭空释放他人的锁。
void action_guards(){Fixture f;auto action=f.start(f.request());auto busy=preview_population_military(f.read(),"officer",f.request());assert(!busy.ok);const auto count=f.economy.cohorts.find("reserve")->headcount;auto context=f.write();must(cancel_population_military(context,"missing"));assert(f.military.military_units[0].mobilizing_action_id==action.id);must(cancel_population_military(context,action.id));f.common.state().actors.find("officer")->action_id.clear();f.common.state().actions.erase(action.id);assert(f.economy.cohorts.find("reserve")->headcount==count&&f.state.enrollments.empty());f.valid();action=f.start(f.request());must(invalidate_office(f.common,f.organization,f.organization_catalog,"macro.office",f.common.tick(),{}));auto denied=f.finish(action);assert(!denied.success&&f.state.enrollments.empty()&&f.economy.cohorts.find("reserve")->headcount==6);f.valid();}
// 登记→真实营粮→明确退籍→再次登记保留旧身份，口粮历史和冷编码均可验证。
void enrollment_release_history(){Fixture f;const auto actors=f.common.actor_order().size();auto enrolled=f.finish(f.start(f.request()));assert(enrolled.success&&f.economy.cohorts.find("reserve")->headcount==3&&f.economy.cohorts.find("serving")->headcount==3&&f.economy.cohorts.find("serving")->labor_capacity==2&&f.common.actor_order().size()==actors);f.valid();const auto next_id=f.common.state().next_instance_id;f.common.state().next_instance_id=1;assert(!validate_population_military(f.read()).ok);f.common.state().next_instance_id=next_id;--f.common.state().identity.tick;assert(!population_military_continuity(f.read()).ok);auto in_flight=f.read();in_flight.phase_finish_tick=f.common.tick()+1;assert(population_military_continuity(in_flight).ok);in_flight.phase_finish_tick=f.common.tick()+2;assert(!population_military_continuity(in_flight).ok);++f.common.state().identity.tick;const auto tokens=f.state.enrollments.find(enrolled.enrollment_id)->terms.member_ids;PopulationReleaseCommand release{{"city","macro.office",0,"officer"},enrolled.enrollment_id,{}};auto released=f.finish(f.start(release));assert(released.success&&f.military.military_units[0].fit.empty()&&f.military.military_units[0].member_ids.empty()&&f.state.enrollments.size()==1&&f.economy.cohorts.find("reserve")->headcount==6&&f.economy.cohorts.find("reserve")->labor_capacity==3);assert(population_military_historical_member(f.read(),tokens[0],3)&&!population_military_historical_member(f.read(),tokens[0],4));f.valid();const auto old=encode_population_military_state(f.state);auto roundtrip=must(decode_population_military_state(old));assert(compare_boundary(old,encode_population_military_state(roundtrip)).exact());CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto snapshot=f.state;must(visit_population_military_checkpoint(writer,snapshot));must(writer.finish());PopulationMilitaryState restored;const auto& input=bytes;CodecVisitor reader(input);must(visit_population_military_checkpoint(reader,restored));must(reader.finish());assert(compare_boundary(old,encode_population_military_state(restored)).exact());auto again=f.finish(f.start(f.request(2,1)));assert(again.success&&again.enrollment_id!=enrolled.enrollment_id&&f.state.enrollments.find(again.enrollment_id)->members[0].member_id!=tokens[0]);f.valid();auto damaged=f.state;damaged.enrollments.find(again.enrollment_id)->members[0].labor_eligible=false;f.state=std::move(damaged);assert(!validate_population_military(f.read()).ok);}
