    TroopDefinition weak;weak.id="infantry";weak.category="infantry";weak.movement=1;weak.attack=1;weak.accuracy=0;weak.movement_costs={{"plain",1},{"forest",1},{"hill",1},{"water",0},{"wall",0}};auto strong=weak;strong.id="enemy.infantry";strong.attack=60;strong.accuracy=95;f.military_catalog.troop_type_ids.push_back(strong.id);f.military_catalog.battle_catalog.troop_types={weak,strong};BattlefieldDefinition field;field.id="field";field.objective_id="goal";field.cells={{0,0,"plain"},{1,0,"plain"}};field.spawns={{0,{0,0}},{1,{1,0}}};f.military_catalog.battle_catalog.battlefields={field};BattleObjectiveDefinition goal;goal.id="goal";goal.kind="repel";goal.max_rounds=3;f.military_catalog.battle_catalog.objectives={goal};MilitaryContactFact contact;contact.id=must(f.common.next_id("contact"));contact.tick=f.common.tick();contact.battlefield_id=field.id;contact.objective_id=goal.id;contact.unit_ids={"enemy.unit","unit"};contact.side_by_army={{"army:enemy",1},{"army:own",0}};contact.army_order_ids={{"army:enemy","campaign:enemy"},{"army:own","campaign:own"}};contact.army_locations={{"army:enemy",f.common.actor("enemy.actor")->location},{"army:own",f.common.actor("officer")->location}};f.military.contact_facts.push_back(contact);must(f.common.append_fact({contact.id,"military_contact","military"}));f.access.battle_seed=17;return must(create_military_battle(f.common,f.military,f.military_catalog,f.access,contact.id));
