// 非终局轮次和随后同边界封账都由原settle生成，不能只接受最终settlement ID。
void intermediate_round_provenance(){Fixture f;f.finish(f.start(f.request(4,2)));const auto id=create_source_battle(f);must(military_supply_step(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));must(step_military_battles(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));assert(f.military.battles.back().phase=="planning"&&!f.military.battle_facts.back().final);auto phase=f.write();phase.phase_finish_tick=f.common.tick()+1;must(validate_population_military_casualty_source(phase.read(),f.military.casualty_facts.back().id));must(reconcile_population_military(phase,f.common.tick()+1));++f.common.state().identity.tick;f.economy.last_step_tick=f.common.tick();f.valid();must(terminate_military_battle(f.common,f.military,f.military_catalog,f.access,id,"cancelled",f.common.tick()));auto committed=f.write();must(validate_population_military_casualty_source(committed.read(),f.military.casualty_facts.back().id));must(reconcile_population_military(committed,f.common.tick()));assert(f.military.battles.back().round_receipt_ids.size()==2);f.valid();}
// 同tick先供养后捕获；原随机轮次实际生成死伤及俘虏，伪孤立/轮次/看管/付款方均拒绝。
void casualties_and_captor_food(){Fixture f;f.catalog.sources.find("source")->initial_morale=1;auto entered=f.finish(f.start(f.request(4,2)));const auto battle_id=create_source_battle(f);must(military_supply_step(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));must(step_military_battles(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));assert(!f.military.casualty_facts.empty());const auto receipt_id=f.military.casualty_facts.back().id;auto phase=f.write();phase.phase_finish_tick=f.common.tick()+1;must(validate_population_military_casualty_source(phase.read(),receipt_id));auto orphan=f.military.casualty_facts.back();orphan.id=must(f.common.next_id("military"));orphan.battle_id="battle:orphan";f.military.casualty_facts.push_back(orphan);must(f.common.append_fact({orphan.id,"military_casualties","military"}));const auto next=f.common.state().next_instance_id;const auto count=f.economy.cohorts.find("serving")->headcount;assert(!validate_population_military_casualty_source(phase.read(),orphan.id).ok);f.military.casualty_facts.pop_back();f.common.state().facts.erase(orphan.id);assert(f.common.state().next_instance_id==next&&f.economy.cohorts.find("serving")->headcount==count);auto& round=f.military.battle_facts.back();auto round_number=round.round;round.round=99;assert(!validate_population_military_casualty_source(phase.read(),receipt_id).ok);round.round=round_number;must(reconcile_population_military(phase,f.common.tick()+1));++f.common.state().identity.tick;f.economy.last_step_tick=f.common.tick();assert(f.military.battles.back().phase=="closed");assert(!f.military.military_units[0].dead.empty()&&!f.military.military_units[0].captured.empty());const auto captive=f.military.military_units[0].captured[0];f.valid();
    const auto next_replay=f.common.state().next_instance_id;auto committed=f.write();must(reconcile_population_military(committed,f.common.tick()));assert(f.common.state().next_instance_id==next_replay);must(military_supply_step(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));++f.common.state().identity.tick;f.economy.last_step_tick=f.common.tick();f.valid();Integer keeper_food=0,former_food=0;for(const auto& receipt:f.military.supply_facts)if(receipt.tick==f.common.tick())for(const auto& mouth:receipt.mouth_ids)if(mouth==captive){keeper_food+=receipt.army_id=="army:enemy";former_food+=receipt.army_id=="army:own"||receipt.garrison_id=="camp";}assert(keeper_food==1&&former_food==0);
    auto saved_military=f.military;f.military.military_units[0].captors[0].second="army:own";auto& keeper=f.military.armies[0].prisoner_ids;keeper.erase(std::remove(keeper.begin(),keeper.end(),captive),keeper.end());f.military.armies[1].prisoner_ids.push_back(captive);assert(!population_military_continuity(f.read()).ok);f.military=saved_military;MilitarySupplyFact* wrong=nullptr;MilitarySupplyFact* right=nullptr;for(auto& receipt:f.military.supply_facts)if(receipt.tick==f.common.tick()){if(receipt.army_id=="army:enemy")right=&receipt;if(receipt.garrison_id=="camp")wrong=&receipt;}assert(right&&wrong);right->mouth_ids.erase(std::remove(right->mouth_ids.begin(),right->mouth_ids.end(),captive),right->mouth_ids.end());--right->required;--right->consumed;wrong->mouth_ids.push_back(captive);std::sort(wrong->mouth_ids.begin(),wrong->mouth_ids.end());++wrong->required;++wrong->consumed;assert(!population_military_continuity(f.read()).ok);f.military=saved_military;
    ArmyLogistics request;request.kind="army_return";request.army_id="army:enemy";request.garrison_id="enemy.camp";auto quote=must(preview_military_lifecycle(f.common,f.military,f.military_catalog,f.access,"enemy.actor",MilitaryCommand{request}));ActionCoreView action{must(f.common.next_id("action")),"army_return","enemy.actor",quote.participants,f.common.tick(),1};f.common.state().actions.insert(action.id,action);f.common.state().actors.find("enemy.actor")->action_id=action.id;must(start_military_logistics(f.common,f.military,f.military_catalog,f.access,action,request,quote));must(military_supply_step(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));action.remaining_ticks=0;auto returned=must(finish_military_logistics(f.common,f.military,f.military_catalog,f.access,action));assert(returned.success);f.common.state().actions.erase(action.id);f.common.state().actors.find("enemy.actor")->action_id.clear();++f.common.state().identity.tick;f.economy.last_step_tick=f.common.tick();f.valid();must(military_supply_step(f.common,f.military,f.military_catalog,f.access,f.common.tick()+1));++f.common.state().identity.tick;f.economy.last_step_tick=f.common.tick();f.valid();bool camp_fed=false;for(const auto& receipt:f.military.supply_facts)if(receipt.tick==f.common.tick()&&receipt.garrison_id=="enemy.camp"&&std::find(receipt.mouth_ids.begin(),receipt.mouth_ids.end(),captive)!=receipt.mouth_ids.end())camp_fed=true;assert(camp_fed);f.military.return_facts[0].prisoner_ids.clear();assert(!population_military_continuity(f.read()).ok);
}

// 同一候选晚期来源故障会留下局部草稿，丢弃候选必须完整保全已发布状态。
void candidate_rollback(){Fixture published;auto action=published.start(published.request());const auto before=encode_population_military_state(published.state);const auto original_population=published.economy.cohorts.find("reserve")->headcount;Fixture candidate;candidate.common=published.common;candidate.economy=published.economy;candidate.organization=published.organization;candidate.military=published.military;candidate.state=published.state;candidate.bind();const auto collision="population_transfer:"+std::to_string(candidate.common.state().next_instance_id+2);must(candidate.common.append_fact({collision,"collision","fixture"}));action.remaining_ticks=0;auto context=candidate.write();auto result=finish_population_military(context,action);assert(!result.ok&&candidate.state.enrollments.size()==1&&candidate.state.action_facts.find(action.id)->success);assert(published.economy.cohorts.find("reserve")->headcount==original_population&&compare_boundary(before,encode_population_military_state(published.state)).exact());}
// 重启只恢复共同持久字段；热点缓存计数差异不能进入新军籍历史，也不能抹掉旧历史。
void durable_authority_restore(){
    Fixture hot;auto* grant=hot.organization_catalog.grants.find("grant");grant->wallet_ids={"city.wallet"};grant->inventory_ids={"city.inventory"};hot.common.state().identity.revision=7;const ResourceKey wallet{ResourceKey::Kind::wallet,"city.wallet"},inventory{ResourceKey::Kind::inventory,"city.inventory"};for(int n=0;n<2;++n)hot.common.invalidate(wallet);for(int n=0;n<10;++n)hot.common.invalidate(inventory);
    auto restore=[&](Fixture& cold){cold.common_catalog=hot.common_catalog;cold.economy_catalog=hot.economy_catalog;cold.economy=hot.economy;cold.organization_catalog=hot.organization_catalog;cold.organization=hot.organization;cold.military_catalog=hot.military_catalog;cold.military=hot.military;cold.catalog=hot.catalog;CodecVisitor::Buffer common_bytes;CodecVisitor common_writer(common_bytes);common_writer.schema_features=common_checkpoint::typed_resource_references;auto common_snapshot=hot.common.state();must(visit_common_checkpoint(common_writer,common_snapshot));must(common_writer.finish());CommonState restored_common;const auto& common_input=common_bytes;CodecVisitor common_reader(common_input);common_reader.schema_features=common_checkpoint::typed_resource_references;must(visit_common_checkpoint(common_reader,restored_common));must(common_reader.finish());cold.common=CommonStore(std::move(restored_common),cold.common_catalog);CodecVisitor::Buffer adapter_bytes;CodecVisitor adapter_writer(adapter_bytes);auto adapter_snapshot=hot.state;must(visit_population_military_checkpoint(adapter_writer,adapter_snapshot));must(adapter_writer.finish());const auto& adapter_input=adapter_bytes;CodecVisitor adapter_reader(adapter_input);must(visit_population_military_checkpoint(adapter_reader,cold.state));must(adapter_reader.finish());cold.bind();};
    auto same_state=[&](const Fixture& cold){assert(compare_boundary(encode_common_state(hot.common.state()),encode_common_state(cold.common.state())).exact());assert(compare_boundary(encode_local_economy_state(hot.economy,true),encode_local_economy_state(cold.economy,true)).exact());assert(compare_boundary(must(export_military_state(hot.military)),must(export_military_state(cold.military))).exact());assert(compare_boundary(encode_population_military_state(hot.state),encode_population_military_state(cold.state)).exact());};
    Fixture cold;restore(cold);same_state(cold);assert(hot.common.read_version(wallet).version==2&&hot.common.read_version(inventory).version==10&&cold.common.read_version(wallet).version==0&&cold.common.read_version(inventory).version==0);auto live=must(check_authority(hot.common,hot.organization,hot.organization_catalog,hot.request().authority,"mobilize_reserve",{ScopeRef::Kind::site,"town"},3));assert(live.resource_versions.size()==2&&live.resource_versions[0].version==2&&live.resource_versions[1].version==10);auto hot_quote=must(preview_population_military(hot.read(),"officer",hot.request()));auto cold_quote=must(preview_population_military(cold.read(),"officer",cold.request()));assert(compare_boundary(encode_population_military_quote(hot_quote),encode_population_military_quote(cold_quote)).exact()&&hot_quote.terms.authority.resource_versions.empty()&&hot_quote.terms.authority.candidate_revision==7);auto enrolled=hot.finish(hot.start(hot.request()));auto restored_enrollment=cold.finish(cold.start(cold.request()));assert(enrolled.success&&restored_enrollment.success&&enrolled.enrollment_id==restored_enrollment.enrollment_id);same_state(cold);
    auto* historical=hot.state.enrollments.find(enrolled.enrollment_id);historical->terms.authority.resource_versions=live.resource_versions;hot.state.action_facts.find(historical->action_id)->terms.authority.resource_versions=live.resource_versions;const auto legacy=encode_population_military_state(hot.state);assert(compare_boundary(legacy,encode_population_military_state(must(decode_population_military_state(legacy)))).exact());restore(cold);assert(compare_boundary(legacy,encode_population_military_state(cold.state)).exact());hot.valid();cold.valid();PopulationReleaseCommand release{{"city","macro.office",0,"officer"},enrolled.enrollment_id,{}};auto hot_released=hot.finish(hot.start(release));auto cold_released=cold.finish(cold.start(release));assert(hot_released.success&&cold_released.success);same_state(cold);assert(hot.state.enrollments.find(enrolled.enrollment_id)->terms.authority.resource_versions[1].version==10&&cold.state.enrollments.find(enrolled.enrollment_id)->terms.authority.resource_versions[1].version==10&&hot.state.action_facts.rows().back().second.terms.authority.resource_versions.empty());hot.valid();cold.valid();
    Fixture revoked;Owner city{Owner::Kind::organization,"city",{}};revoked.common.state().wallets.insert("authority.wallet",{"authority.wallet",city,0,{}});revoked.organization_catalog.grants.find("grant")->wallet_ids={"authority.wallet"};auto action=revoked.start(revoked.request());const auto before_count=revoked.economy.cohorts.find("reserve")->headcount;const auto before_counter=revoked.common.read_version({ResourceKey::Kind::wallet,"authority.wallet"}).version;revoked.common.state().wallets.find("authority.wallet")->owner.id="enemy";assert(revoked.common.read_version({ResourceKey::Kind::wallet,"authority.wallet"}).version==before_counter);auto denied=revoked.finish(action);assert(!denied.success&&denied.code=="AuthorityResourceMismatch"&&revoked.state.enrollments.empty()&&revoked.economy.cohorts.find("reserve")->headcount==before_count);
}

// 真实源码供养入口可执行的来源安全夹具；实战生成伤亡由中央组合节点另行证明。
int main(int argc,char** argv){if(argc==2&&StableId(argv[1])=="--authority-restore"){durable_authority_restore();std::cout<<"population_military_authority_restore: PASS (hot/cold exact durable state, live resource checks, old-counter history preserved)\n";return 0;}action_guards();enrollment_release_history();retired_training();intermediate_round_provenance();casualties_and_captor_food();candidate_rollback();std::cout<<"population_military_source: PASS (half-day enrollment/release, duplicate/cancel/authority loss, completed/cancelled training retirement, real garrison/captor food, production intermediate/final settlement/provenance corruption/keeper return, immutable labor origins, historical rations, codec/checkpoint, candidate isolation)\n";}
